replace_once(
    template,
    '''  <h2>Automated stream health</h2>\n''',
    '''  <h2>Source concentration reliability</h2>\n  <p class="muted">\n    Stable channels grouped by exact stream hostname and by provenance class.\n    Official broadcaster, broadcaster CDN and third-party relay counts use the\n    same evidence as feed-quality scoring. Unknown provenance stays Unclassified.\n    Concentration warnings are reserved for third-party relay hosts carrying a\n    material share of one country's stable playlist.\n  </p>\n  <div id="sourceConcentrationSummary" class="audit-summary">\n    <div class="card"><div class="value">…</div><div class="label">Loading source concentration</div></div>\n  </div>\n  <h3>Source type by country</h3>\n  <div id="sourceConcentrationCountrySummary" class="audit-summary">\n    <div class="card"><div class="value">…</div><div class="label">Loading country concentration</div></div>\n  </div>\n  <p id="sourceConcentrationVisibleCount" class="muted">Loading source-concentration.json…</p>\n  <div class="table-wrap">\n    <table id="sourceConcentrationTable">\n      <thead>\n        <tr><th>Country</th><th>Hostname / CDN</th><th>Type</th><th>Stable channels</th><th>Country share</th><th>Relay exposure</th><th>Risk</th><th>Channels</th></tr>\n      </thead>\n      <tbody><tr><td colspan="8" class="muted">Loading hostname concentration…</td></tr></tbody>\n    </table>\n  </div>\n\n  <h2>Automated stream health</h2>\n''',
)

js = ROOT / "static" / "dashboard.js"
replace_once(
    js,
    '''  renderHealthSummary();\n  renderHealthCountrySummary();\n  applyHealthFilters();\n''',
    '''  renderHealthSummary();\n  renderHealthCountrySummary();\n  applyHealthFilters();\n  renderSourceConcentration();\n''',
)
replace_once(
    js,
    '''// Automated health ---------------------------------------------------------\n''',
    '''// Source concentration -----------------------------------------------------\nconst sourceConcentrationSummary = document.getElementById('sourceConcentrationSummary');\nconst sourceConcentrationCountrySummary = document.getElementById('sourceConcentrationCountrySummary');\nconst sourceConcentrationVisibleCount = document.getElementById('sourceConcentrationVisibleCount');\nconst sourceConcentrationTableBody = document.querySelector('#sourceConcentrationTable tbody');\nlet sourceConcentrationData = null;\n\nfunction concentrationBadgeClass(risk) {\n  if (risk === 'critical' || risk === 'high') return 'rejected';\n  if (risk === 'warning') return 'review';\n  return 'base';\n}\n\nfunction sourceTypeShortLabel(sourceType) {\n  if (sourceType === 'Official broadcaster') return 'Official';\n  if (sourceType === 'Broadcaster CDN') return 'Broadcaster CDN';\n  if (sourceType === 'Third-party relay') return 'Relay';\n  return 'Unclassified';\n}\n\nfunction renderSourceConcentration() {\n  if (!sourceConcentrationData) return;\n  const data = sourceConcentrationData;\n  const countries = data.countries || {};\n  const summary = data.summary || {};\n  const selectedCodes = SUPPORTED_COUNTRIES\n    .filter(code => countries[code])\n    .filter(countryMatches);\n\n  const visibleCountries = selectedCountry === 'ALL'\n    ? selectedCodes\n    : selectedCodes.filter(code => code === selectedCountry);\n  const visibleTotal = visibleCountries.reduce((sum, code) => sum + Number(countries[code]?.stable_channels || 0), 0);\n  const typeCounts = {\n    'Official broadcaster': 0,\n    'Broadcaster CDN': 0,\n    'Third-party relay': 0,\n    'Unclassified': 0,\n  };\n  for (const code of visibleCountries) {\n    for (const row of countries[code]?.source_types || []) {\n      typeCounts[row.source_type] = (typeCounts[row.source_type] || 0) + Number(row.channels || 0);\n    }\n  }\n  const visibleFlags = (data.flags || []).filter(flag => countryMatches(flag.country_code));\n  const pct = value => visibleTotal ? (100 * Number(value || 0) / visibleTotal).toFixed(1) : '0.0';\n\n  if (sourceConcentrationSummary) {\n    sourceConcentrationSummary.innerHTML = `\n      <div class="card"><div class="value">${visibleTotal}</div><div class="label">Stable channels measured</div></div>\n      <div class="card"><div class="value">${typeCounts['Official broadcaster']}</div><div class="label">Official broadcaster (${pct(typeCounts['Official broadcaster'])}%)</div></div>\n      <div class="card"><div class="value">${typeCounts['Broadcaster CDN']}</div><div class="label">Broadcaster CDN (${pct(typeCounts['Broadcaster CDN'])}%)</div></div>\n      <div class="card"><div class="value">${typeCounts['Third-party relay']}</div><div class="label">Third-party relay (${pct(typeCounts['Third-party relay'])}%)</div></div>\n      <div class="card"><div class="value">${typeCounts.Unclassified}</div><div class="label">Unclassified (${pct(typeCounts.Unclassified)}%)</div></div>\n      <div class="card"><div class="value">${visibleFlags.length}</div><div class="label">Relay concentration flags</div></div>`;\n  }\n\n  if (sourceConcentrationCountrySummary) {\n    sourceConcentrationCountrySummary.innerHTML = visibleCountries.map(code => {\n      const info = countries[code] || {};\n      const counts = Object.fromEntries((info.source_types || []).map(row => [row.source_type, row]));\n      const relay = counts['Third-party relay'] || { channels: 0, percent: 0 };\n      const cdn = counts['Broadcaster CDN'] || { channels: 0, percent: 0 };\n      const official = counts['Official broadcaster'] || { channels: 0, percent: 0 };\n      const unknown = counts.Unclassified || { channels: 0, percent: 0 };\n      return `<div class="card" data-country="${esc(code)}">\n        <div class="value">${Number(relay.percent || 0).toFixed(1)}%</div>\n        <div class="label">${code} third-party relay (${Number(relay.channels || 0)}/${Number(info.stable_channels || 0)})</div>\n        <div class="detail">Official ${official.channels || 0} · CDN ${cdn.channels || 0} · Unclassified ${unknown.channels || 0}</div>\n      </div>`;\n    }).join('');\n  }\n\n  const hostRows = [];\n  for (const code of visibleCountries) {\n    for (const host of countries[code]?.hostnames || []) {\n      hostRows.push({ ...host, country_code: code });\n    }\n  }\n  if (sourceConcentrationTableBody) {\n    sourceConcentrationTableBody.innerHTML = hostRows.map(host => {\n      const typeDetail = Object.entries(host.source_types || {})\n        .map(([type, count]) => `${sourceTypeShortLabel(type)} ${count}`)\n        .join(' · ');\n      const channelNames = Array.isArray(host.channel_names) ? host.channel_names : [];\n      const shown = channelNames.slice(0, 8).join(', ');\n      const extra = channelNames.length > 8 ? ` +${channelNames.length - 8} more` : '';\n      const risk = String(host.risk || 'none');\n      return `<tr data-country="${esc(host.country_code)}">\n        <td><strong>${esc(host.country_code)}</strong></td>\n        <td>${esc(host.hostname)}</td>\n        <td>${esc(host.source_type || 'Unclassified')}<div class="detail">${esc(typeDetail)}</div></td>\n        <td>${Number(host.channels || 0)}</td>\n        <td>${Number(host.country_percent || 0).toFixed(1)}%</td>\n        <td>${Number(host.third_party_relay_channels || 0)} (${Number(host.third_party_relay_percent || 0).toFixed(1)}%)</td>\n        <td><span class="badge ${concentrationBadgeClass(risk)}">${esc(risk === 'none' ? 'OK' : risk.toUpperCase())}</span></td>\n        <td class="detail">${esc(shown + extra)}</td>\n      </tr>`;\n    }).join('') || '<tr><td colspan="8" class="muted">No source concentration data for this country.</td></tr>';\n  }\n  if (sourceConcentrationVisibleCount) {\n    sourceConcentrationVisibleCount.textContent = `Showing ${hostRows.length} hostname dependencies · ${visibleFlags.length} relay concentration flags`;\n  }\n}\n\nfetch('source-concentration.json', { cache: 'no-store' })\n  .then(response => { if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json(); })\n  .then(data => { sourceConcentrationData = data; renderSourceConcentration(); })\n  .catch(error => {\n    if (sourceConcentrationSummary) sourceConcentrationSummary.innerHTML = '<div class="card"><div class="value">—</div><div class="label">Source concentration unavailable</div></div>';\n    if (sourceConcentrationTableBody) sourceConcentrationTableBody.innerHTML = `<tr><td colspan="8">source-concentration.json could not be loaded: ${esc(error.message)}</td></tr>`;\n    if (sourceConcentrationVisibleCount) sourceConcentrationVisibleCount.textContent = 'source-concentration.json is not available yet.';\n  });\n\n// Automated health ---------------------------------------------------------\n''',
)


# ---------------------------------------------------------------------------
# Tests: taxonomy consistency, aggregation/risk, and dashboard wiring.
# ---------------------------------------------------------------------------
(ROOT / "tests" / "test_source_concentration.py").write_text(
    '''import unittest\nfrom pathlib import Path\n\nfrom feed_quality import classify_feed_source, score_feed_quality\nfrom source_concentration import build_source_concentration\n\n\nclass SourceClassificationTests(unittest.TestCase):\n    def test_requested_source_types_reuse_feed_quality_evidence(self):\n        official = {\n            "url": "https://official.example/live.m3u8",\n            "_audit": {"quality_flags": ["official_broadcaster"]},\n        }\n        cdn = {\n            "url": "https://cdn.example/live.m3u8",\n            "_audit": {"quality_flags": ["broadcaster_cdn"]},\n        }\n        relay = {\n            "url": "https://relay.example/live.m3u8",\n            "_audit": {"quality_flags": ["provider_relay"]},\n        }\n        unknown = {"url": "https://unknown.example/live.m3u8", "_audit": {}}\n\n        self.assertEqual(classify_feed_source(official)["source_type"], "Official broadcaster")\n        self.assertEqual(classify_feed_source(cdn)["source_type"], "Broadcaster CDN")\n        self.assertEqual(classify_feed_source(relay)["source_type"], "Third-party relay")\n        self.assertEqual(classify_feed_source(unknown)["source_type"], "Unclassified")\n\n        score = score_feed_quality(relay, {}, context={})\n        keys = {component["key"] for component in score["components"]}\n        self.assertIn("provider_relay", keys)\n\n    def test_relay_wins_conflicting_provenance_classification(self):\n        entry = {\n            "url": "https://relay.example/live.m3u8",\n            "_audit": {\n                "quality_flags": [\n                    "official_broadcaster",\n                    "broadcaster_cdn",\n                    "provider_relay",\n                ]\n            },\n        }\n        result = classify_feed_source(entry)\n        self.assertTrue(result["official_broadcaster"])\n        self.assertTrue(result["broadcaster_cdn"])\n        self.assertTrue(result["provider_relay"])\n        self.assertEqual(result["source_type"], "Third-party relay")\n\n\nclass SourceConcentrationTests(unittest.TestCase):\n    def test_counts_percentages_and_flags_large_relay_dependency(self):\n        cfg = {\n            "source_concentration": {\n                "warning_min_channels": 2,\n                "warning_percent": 20,\n                "high_min_channels": 3,\n                "high_percent": 30,\n                "critical_min_channels": 4,\n                "critical_percent": 40,\n            }\n        }\n        entries = []\n        for index in range(4):\n            entries.append({\n                "country_code": "HU",\n                "channel_name": f"Relay {index}",\n                "url": f"https://relay.example/{index}.m3u8",\n                "_audit": {"quality_flags": ["provider_relay"]},\n            })\n        for index in range(3):\n            entries.append({\n                "country_code": "HU",\n                "channel_name": f"Official {index}",\n                "url": f"https://official{index}.example/live.m3u8",\n                "_audit": {"quality_flags": ["official_broadcaster"]},\n            })\n        for index in range(2):\n            entries.append({\n                "country_code": "HU",\n                "channel_name": f"CDN {index}",\n                "url": f"https://cdn.example/{index}.m3u8",\n                "_audit": {"quality_flags": ["broadcaster_cdn"]},\n            })\n        entries.append({\n            "country_code": "HU",\n            "channel_name": "Unknown",\n            "url": "https://unknown.example/live.m3u8",\n            "_audit": {},\n        })\n\n        report = build_source_concentration(entries, cfg, generated_at="2026-08-12T18:00:00+02:00")\n        hu = report["countries"]["HU"]\n        counts = {row["source_type"]: row for row in hu["source_types"]}\n\n        self.assertEqual(hu["stable_channels"], 10)\n        self.assertEqual(counts["Third-party relay"]["channels"], 4)\n        self.assertEqual(counts["Third-party relay"]["percent"], 40.0)\n        self.assertEqual(counts["Official broadcaster"]["channels"], 3)\n        self.assertEqual(counts["Broadcaster CDN"]["channels"], 2)\n        self.assertEqual(counts["Unclassified"]["channels"], 1)\n\n        relay_host = next(row for row in hu["hostnames"] if row["hostname"] == "relay.example")\n        self.assertEqual(relay_host["channels"], 4)\n        self.assertEqual(relay_host["third_party_relay_percent"], 40.0)\n        self.assertEqual(relay_host["risk"], "critical")\n        self.assertEqual(report["flags"][0]["hostname"], "relay.example")\n\n    def test_broadcaster_cdn_concentration_is_measured_but_not_relay_flagged(self):\n        entries = [\n            {\n                "country_code": "SK",\n                "channel_name": f"JOJ {index}",\n                "url": f"https://joj-cdn.example/{index}.m3u8",\n                "_audit": {"quality_flags": ["broadcaster_cdn"]},\n            }\n            for index in range(12)\n        ]\n        report = build_source_concentration(entries, generated_at="now")\n        host = report["countries"]["SK"]["hostnames"][0]\n        self.assertEqual(host["country_percent"], 100.0)\n        self.assertEqual(host["source_type"], "Broadcaster CDN")\n        self.assertEqual(host["risk"], "none")\n        self.assertEqual(report["flags"], [])\n\n    def test_dashboard_loads_generated_source_concentration_report(self):\n        root = Path(__file__).resolve().parents[1]\n        template = (root / "templates" / "dashboard.html").read_text(encoding="utf-8")\n        js = (root / "static" / "dashboard.js").read_text(encoding="utf-8")\n        self.assertIn('id="sourceConcentrationSummary"', template)\n        self.assertIn('id="sourceConcentrationTable"', template)\n        self.assertIn('source-concentration.json', template)\n        self.assertIn("fetch('source-concentration.json'", js)\n        self.assertIn('renderSourceConcentration();', js)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''',
    encoding="utf-8",
)


# ---------------------------------------------------------------------------
# Short operator-facing documentation.
# ---------------------------------------------------------------------------
(ROOT / "docs" / "source-concentration.md").write_text(
    '''# Source concentration reliability\n\n`public/source-concentration.json` is generated from the exact stable entries\nthat are published to `tv.m3u`. It answers a different question from per-stream\nhealth: how much of a country can fail at once if one hostname or relay disappears?\n\n## Source taxonomy\n\nThe report reuses `feed_quality.py` provenance evidence instead of maintaining a\nsecond classifier:\n\n- **Official broadcaster** — explicitly marked direct/official broadcaster source.\n- **Broadcaster CDN** — explicitly marked broadcaster-owned/operated CDN path.\n- **Third-party relay** — explicitly marked or recognized provider relay; this is\n  the same condition that receives the feed-quality relay penalty.\n- **Unclassified** — no safe provenance classification. Unknown is deliberately\n  not treated as relay.\n\nIf evidence conflicts, Third-party relay wins the display classification, then\nBroadcaster CDN, then Official broadcaster. Scoring still preserves all underlying\nsignals for backward compatibility.\n\n## Concentration warnings\n\nEvery hostname is counted by country and gets a share of that country's stable\nchannels. Default alert thresholds apply only to **third-party relay channels on\nthe same hostname**:\n\n- warning: at least 5 channels and 15% of the country\n- high: at least 10 channels and 20% of the country\n- critical: at least 20 channels and 30% of the country\n\nBoth the count and percentage threshold must be met. Broadcaster CDN concentration\nis still visible in the dashboard/table, but is not labeled as third-party relay\nrisk. Thresholds can be overridden with a top-level `source_concentration` object\nin `config.json`.\n''',
    encoding="utf-8",
)
